package com.lolfm.champion;import static org.assertj.core.api.Assertions.*;import java.util.Map;import org.junit.jupiter.api.Test;
class LevelPowerCurveTest{@Test void anchorsInterpolationAndClampAreDeterministic(){var c=new LevelPowerCurve("X",Map.of(1,-.2,6,-.1,11,.1,16,.3,18,.4));assertThat(c.valueAt(1)).isEqualTo(-.2);assertThat(c.valueAt(6)).isEqualTo(-.1);assertThat(c.valueAt(8)).isCloseTo(-.02,within(1e-12));assertThat(c.valueAt(11)).isEqualTo(.1);assertThat(c.valueAt(16)).isEqualTo(.3);assertThat(c.valueAt(18)).isEqualTo(.4);assertThat(c.valueAt(-99)).isEqualTo(-.2);assertThat(c.valueAt(99)).isEqualTo(.4);}}
